'use client';
import {apiFetch,setEditorToken} from '../lib/network';
import {useEffect,useRef,useState} from 'react';
import {ArrowDownLeft,ArrowUpRight,ArrowRight,Plus,ChevronDown,ChevronRight,Check,CheckCheck,CloudCheck,CloudOff,LoaderCircle,LayoutDashboard,Users,Activity,ArrowLeftRight,History,SlidersHorizontal,Spade,Search,X,Download,Upload,Copy,LockKeyhole,LockKeyholeOpen,RotateCcw,NotebookPen,CheckCircle2,AlertCircle,Coins,Wallet,Headphones,Play,Pause,Club,Share2,Mail,Send,BellRing,Ban} from 'lucide-react';
import {EmailSettings} from '../components/email-settings';
import {Intro,shouldPlayIntro} from '../components/intro';
import {Avatar,PlayerCard} from '../components/player-visuals';
import {playerProfiles,outstandingDebts} from '../lib/analytics.mjs';
import {deliverQueuedEmails} from '../lib/email-delivery';
import {usePlayerContacts} from '../lib/use-player-contacts';
import {Dashboard} from '../components/dashboard';
import {readRoute,routePath} from '../lib/navigation.mjs';
import {settlementSteps,balanceCalculation} from '../lib/analytics.mjs';
import {MusicPanel,SpotifyMark} from '../components/music-panel';
import {useMusic} from '../lib/use-music';
import {useLedger} from '../lib/use-ledger';
import {stats,playerStats,participants,balances,simplify,money,signedMoney,METHODS,BANK_ID} from '../lib/engine.mjs';

type Page='owed'|'game'|'missing'|'overview'|'players'|'activity'|'settlements'|'history'|'settings'|'music';
type Modal='email'|'session'|'player'|'edit-player'|'buyin'|'cashout'|'transfer'|'close'|'notes'|'share'|'void'|'allocate'|'unlock'|'';
const navigation=[{id:'overview',label:'Dashboard',icon:LayoutDashboard},{id:'history',label:'Games',icon:History},{id:'players',label:'Players',icon:Users},{id:'activity',label:'Activity',icon:Activity},{id:'owed',label:'Settlements',icon:ArrowLeftRight},{id:'music',label:'Music',icon:Headphones}] as const;
const formatTime=(at:string|null)=>at?new Date(at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}):'Time unknown';
const formatDate=(at:string|null)=>at?new Date(at).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'Date not recorded';
function download(filename:string,body:string,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function Empty({icon:Icon=Spade,title,detail,children}:{icon?:any,title:string,detail:string,children?:React.ReactNode}){return <div className="empty"><span className="empty-icon"><Icon size={25}/></span><h3>{title}</h3><p>{detail}</p>{children&&<div className="empty-actions">{children}</div>}</div>;}
export default function FeltClub(){
 const {data,ready,online,pending,saving,updatedAt,error,clearError,dispatch,retry}=useLedger();
 const initialRoute=typeof window!=='undefined'?readRoute(window.location.pathname):readRoute('/');
 const [page,setPage]=useState<Page>(()=>typeof window!=='undefined'&&(new URLSearchParams(window.location.search).has('code')||new URLSearchParams(window.location.search).has('error'))?'music':initialRoute.page as Page),[sessionId,setSessionId]=useState(initialRoute.sessionId),[modal,setModal]=useState<Modal>(''),[preset,setPreset]=useState<any>({}),[formError,setFormError]=useState(''),[notice,setNotice]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('all'),[selectedPlayer,setSelectedPlayer]=useState('');
 const [motion,setMotion]=useState(()=>{if(typeof window==='undefined')return false;try{return !window.matchMedia('(prefers-reduced-motion: reduce)').matches&&localStorage.getItem('felt-club.motion')!=='off';}catch{return false;}});
 const [intro,setIntro]=useState(shouldPlayIntro);const videoRef=useRef<HTMLVideoElement>(null);
 useEffect(()=>{try{localStorage.setItem('felt-club.motion',motion?'on':'off');}catch{}const v=videoRef.current;if(v){if(motion)void v.play().catch(()=>{});else v.pause();}},[motion]);
 useEffect(()=>{const preference=window.matchMedia('(prefers-reduced-motion: reduce)');const changed=()=>{if(preference.matches)setMotion(false);};preference.addEventListener('change',changed);return()=>preference.removeEventListener('change',changed);},[]);
 const [editor,setEditor]=useState(false);const editorRef=useRef(false),afterUnlock=useRef<any>(null);
 const fileRef=useRef<HTMLInputElement>(null),dialogRef=useRef<HTMLDialogElement>(null),returnFocus=useRef<HTMLElement|null>(null);
 const s=sessionId?data.sessions.find((x:any)=>x.id===sessionId):data.sessions.at(-1),st=s?stats(s):null,ids=s?participants(s):[];
 const debts=outstandingDebts(data),debtors=[...debts].map(([id,items]:any)=>({id,items,total:items.reduce((n:number,d:any)=>n+d.amount,0)})).sort((a:any,b:any)=>b.total-a.total);
 const music=useMusic(s?.id,editor);
 const privateProfiles=usePlayerContacts(editor);
 useEffect(()=>{if(editor)void deliverQueuedEmails().catch(()=>{});},[editor]);
 const person=(id:string)=>id===BANK_ID?(s?.mode==='decentralized'?'Table pot':'Bank'):data.players.find((x:any)=>x.id===id)?.name||'Unknown player';
 const open=(type:Modal,values:any={})=>{if(type&&type!=='share'&&type!=='unlock'&&!editorRef.current){afterUnlock.current={modal:type,preset:values};type='unlock';}returnFocus.current=document.activeElement as HTMLElement;setPreset(values);setSelectedPlayer(values.playerId||'');setFormError('');setModal(type);};
 useEffect(()=>{void apiFetch('/api/access').then(r=>r.json()).then((v:any)=>{setEditor(v.editor);editorRef.current=v.editor;}).catch(()=>{});const unlock=()=>{setEditor(false);editorRef.current=false;setModal('unlock');};window.addEventListener('pokerbank:unlock',unlock);return()=>window.removeEventListener('pokerbank:unlock',unlock);},[]);
 const toast=(message:string)=>{setNotice(message);};
 useEffect(()=>{if(notice){const timer=setTimeout(()=>setNotice(''),4500);return()=>clearTimeout(timer);}},[notice]);
 useEffect(()=>{if(modal&&!dialogRef.current?.open){dialogRef.current?.showModal();}if(!modal&&dialogRef.current?.open){dialogRef.current.close();returnFocus.current?.focus();}},[modal]);
 useEffect(()=>{const listener=(e:KeyboardEvent)=>{if(e.ctrlKey||e.metaKey||e.altKey||modal||['INPUT','TEXTAREA','SELECT'].includes((e.target as HTMLElement)?.tagName))return;if(e.key.toLowerCase()==='b'&&s?.status==='open'){e.preventDefault();open('buyin');}if(e.key.toLowerCase()==='n'){e.preventDefault();open('session');}};window.addEventListener('keydown',listener);return()=>window.removeEventListener('keydown',listener);},[modal,s]);
 const act=(type:string,payload:any,message?:string)=>{if(!editorRef.current){afterUnlock.current={action:type,payload,message};open('unlock');return null;}try{const id=dispatch(type,payload);if(message)toast(message);return id;}catch(e){setFormError(e instanceof Error?e.message:'Something went wrong.');return null;}};
 const go=(p:Page,id='')=>{const path=routePath(p,id);window.history.pushState({},'',path);setPage(p);setSessionId(id);setQuery('');setFilter('all');window.scrollTo({top:0,behavior:'instant'});};
 const navigate=(p:Page)=>{if(['game','activity','settlements'].includes(p)){if(s)go(p,s.id);else go('history');}else go(p);};
 const selectGame=(id:string,tab:'game'|'settlements'='game')=>go(tab,id);
 useEffect(()=>{const pop=()=>{const route=readRoute(window.location.pathname);setPage(route.page as Page);setSessionId(route.sessionId);setQuery('');setFilter('all');};window.addEventListener('popstate',pop);return()=>window.removeEventListener('popstate',pop);},[]);
 useEffect(()=>{document.title=`${page==='game'&&s?s.title:page==='overview'?'Dashboard':page==='history'?'Games':page.charAt(0).toUpperCase()+page.slice(1)} · Felt Club Poker OS`;},[page,s]);
 const exportJSON=()=>download(`felt-club-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(data,null,2));
 const exportCSV=()=>{
  if(!s)return;const cell=(v:any)=>{let value=String(v??'');if(/^[\s]*[=+@\-\t\r]/.test(value))value="'"+value;return '"'+value.replace(/"/g,'""')+'"';};
  const rows=[['Session','Timestamp','Type','Player','From','To','Amount USD','Method','Status','Note','Voided']];
  for(const e of s.entries)rows.push([s.title,e.at||'',e.type,e.playerId?person(e.playerId):'',e.from?person(e.from):'',e.to?person(e.to):'',(e.amount/100).toFixed(2),e.method||'',e.status||'',e.note||'',e.voidedAt||'']);
  for(const a of s.adjustments)rows.push([s.title,a.at||'','adjustment',person(a.playerId),'','',(a.amount/100).toFixed(2),'','',a.note||'',a.voidedAt||'']);
  download(`felt-club-${s.id}.csv`,'\ufeff'+rows.map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv');
 };
 async function importFile(file:File){try{const ledger=JSON.parse(await file.text());if(act('import',{ledger},'Your games were imported. Existing history was preserved.'))navigate('overview');}catch(e){toast(e instanceof Error?e.message:'Could not read that backup.');}}
 async function submit(event:React.FormEvent<HTMLFormElement>){
  event.preventDefault();setFormError('');const values=Object.fromEntries(new FormData(event.currentTarget).entries()) as any;let type:string=modal,payload:any={...values,sessionId:s?.id};
  if(modal==='unlock'){try{const response=await apiFetch('/api/access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({passcode:values.passcode})});const result:any=await response.json();if(!response.ok){setFormError(result.error);return;}if(result.token)setEditorToken(result.token);setEditor(true);editorRef.current=true;setFormError('');setModal('');toast('Editing unlocked.');const next=afterUnlock.current;afterUnlock.current=null;if(next?.modal){setPreset(next.preset);setSelectedPlayer(next.preset?.playerId||'');setModal(next.modal);}if(next?.action)act(next.action,next.payload,next.message);void retry();}catch{setFormError('Could not connect. Please try again.');}return;}
  if(modal==='email'){const playerIds=new FormData(event.currentTarget).getAll('playerIds').map(String);if(!playerIds.length){setFormError('Choose at least one player with an email address.');return;}type='send-update';payload={sessionId:s?.id,playerIds};}
  if(modal==='session'){type='create-session';}
  if(modal==='player')type='add-player';
  if(modal==='edit-player'){if(!privateProfiles.ready){setFormError(privateProfiles.error||'Email addresses are still loading. Try again in a moment.');return;}payload.playerId=preset.playerId;}
  if(modal==='player'||modal==='edit-player')payload.emailEnabled=values.emailEnabled==='on';
  if(modal==='buyin'||modal==='cashout'){
   if(values.playerId==='__new'){
    const newId=act('add-player',{name:values.newName});if(!newId)return;payload.playerId=newId;
   }
   payload.received=values.received==='on';
  }
  if(modal==='transfer'){payload.paid=values.paid==='on';}
  if(modal==='close')type='close-session';
  if(modal==='void'){type='void-entry';payload.entryId=preset.entryId;}
  const actionId=act(type,payload,modal==='email'?`Emails queued for ${payload.playerIds.length} player${payload.playerIds.length===1?'':'s'}.`:modal==='session'?'Game created.':modal==='buyin'?'Buy-in recorded.':modal==='cashout'?'Chip cash-out recorded.':modal==='transfer'?'Payment recorded.':'Saved.');if(actionId){setModal('');if(modal==='session')selectGame(actionId);if(modal==='close')navigate('settlements');}
 }
 const syncLabel=!online?(pending?`${pending} update${pending===1?'':'s'} waiting`:'Offline · saved copy'):saving?'Saving to cloud…':pending?`${pending} update${pending===1?'':'s'} queued`:ready?'All changes saved':'Connecting…';
 const SyncIcon=!online?CloudOff:saving||!ready?LoaderCircle:CloudCheck;
 const gameSelect=<div className="game-select"><Spade size={15}/><select aria-label="Choose game" value={s?.id||''} onChange={e=>selectGame(e.target.value)}>{!data.sessions.length&&<option>No game selected</option>}{[...data.sessions].reverse().map((x:any)=><option key={x.id} value={x.id}>{x.title}</option>)}</select><ChevronDown size={13}/></div>;
 function Feed({entries,full=false}:{entries:any[],full?:boolean}){return entries.length?<div className={`feed ${full?'full-feed':''}`}>{entries.map(e=>{
  const isBuy=e.type==='buyin',isCash=e.type==='cashout',deferred=isBuy&&s?.mode==='decentralized'&&e.status!=='received';
  return <div key={e.id} className={`feed-row ${e.voidedAt?'voided':''}`}><span className={`feed-icon ${isBuy?'in':isCash?'out':'transfer'}`}>{isBuy?<ArrowDownLeft size={17}/>:isCash?<ArrowUpRight size={17}/>:<ArrowLeftRight size={17}/>}</span><div className="feed-detail"><div className="feed-description"><b>{isBuy?'Buy-in':isCash?'Cash-out':'Payment'}</b><span>·</span><span>{e.type==='transfer'?`${person(e.from)} → ${person(e.to)}`:person(e.playerId)}</span></div><div className="feed-meta">{formatTime(e.at)}<span>·</span>{e.voidedAt?'Voided':deferred?'Settle at end':isCash?'Chips counted':e.status==='received'?'Received':e.status==='paid'?'Paid':'Pending'}{full&&e.method&&<> · {e.method}</>}</div>{full&&e.note&&<p className="entry-note">{e.note}</p>}{full&&!e.voidedAt&&<div className="feed-actions">{e.type==='transfer'&&e.status==='pending'&&<button onClick={()=>act('confirm-entry',{sessionId:s.id,entryId:e.id},'Payment confirmed.')}><Check size={12}/>Mark paid</button>}{isBuy&&!deferred&&e.status==='pending'&&<button onClick={()=>act('confirm-entry',{sessionId:s.id,entryId:e.id},'Buy-in received.')}><Check size={12}/>Mark received</button>}<button onClick={()=>open('void',{entryId:e.id})}><RotateCcw size={12}/>Void / correct</button></div>}</div><strong className="feed-amount">{money(e.amount)}</strong></div>;
 })}</div>:<Empty icon={Activity} title="No activity yet." detail="Recorded entries will appear here."/>;}
 const ledgerPanel=<section className="panel ledger-panel"><div className="panel-heading"><div><h2>Ledger <span className="count">{ids.length}</span></h2></div><button className="icon-button" title="Download session CSV" aria-label="Download session CSV" onClick={exportCSV} disabled={!s}><Download size={17}/></button></div>{ids.length?<div className="table-scroll"><table><thead><tr><th>Player</th><th>Buy-ins</th><th>Cash-out</th><th>Net result</th><th>Status</th><th aria-label="Actions"/></tr></thead><tbody>{ids.map((id:any,index:number)=>{
  const ps=playerStats(s,id),net=balances(s).get(id)||0,hasCashed=s.entries.some((e:any)=>e.type==='cashout'&&e.playerId===id&&!e.voidedAt),closed=s.status==='closed';
  return <tr key={id}><td><div className="player-cell"><Avatar name={person(id)} index={index}/><span>{person(id)}<small>{s.entries.filter((e:any)=>e.type==='buyin'&&e.playerId===id&&!e.voidedAt).length} buy-in{s.entries.filter((e:any)=>e.type==='buyin'&&e.playerId===id&&!e.voidedAt).length===1?'':'s'}</small></span></div></td><td className="numeric">{money(ps.bought)}</td><td className={`numeric ${!hasCashed?'muted':''}`}>{hasCashed?money(ps.cashed+ps.adjustment):'Not recorded'}</td><td className={`numeric strong ${hasCashed?(ps.net>0?'positive':ps.net<0?'negative':''):''}`}>{hasCashed?signedMoney(ps.net):<span className="muted">Not recorded</span>}</td><td><span className={`status-pill ${closed&&!net?'green':hasCashed?'neutral':'live'}`}><i/>{closed?(net===0?'Settled':net>0?'To receive':'To pay'):hasCashed?'Cashed out':'At the table'}</span></td><td><button className="row-action" aria-label={`Actions for ${person(id)}`} title={hasCashed?'View activity':'Record buy-in'} onClick={()=>hasCashed?navigate('activity'):open('buyin',{playerId:id})}>{hasCashed?<ChevronRight size={16}/>:<Plus size={16}/>}</button></td></tr>;
 })}</tbody></table></div>:<Empty icon={Users} title="No entries yet." detail="Record the first buy-in to begin the ledger.">{s?.status==='open'&&<button className="button primary" onClick={()=>open('buyin')}><Plus size={16}/>First buy-in</button>}</Empty>}{ids.length>0&&<div className="panel-foot"><span><Coins size={12}/>{s?.mode==='centralized'?'Banker':'Pay at end'}</span><span>{money(st?.totalIn||0)} in play</span></div>}</section>
 function GamePage(){return <>
  <section className="table-hero"><div className="hero-content"><div className="hero-ornament" aria-hidden="true"><i/><Club size={28} strokeWidth={1.1}/><i/></div><div className="hero-top"><span className={`live-label ${s?.status==='closed'?'closed':''}`}>{s?s.status==='open'?'In progress':'Closed':'No game'}</span></div><h1>{s?s.title:<>Poker night.</>}</h1><p>{s?<>{ids.length} player{ids.length===1?'':'s'} · {s.mode==='centralized'?'Banker':'Pay at end'}</>:<>Ledger</>}</p><div className="hero-actions">{s?.status==='open'?<><button className="button gold" onClick={()=>open('buyin')}><Plus size={17}/>Record buy-in <kbd>B</kbd></button><button className="button hero-secondary" onClick={()=>open('cashout')}><ArrowUpRight size={16}/>Cash out</button><button className="button hero-tertiary" onClick={()=>navigate('settlements')}><ArrowLeftRight size={16}/>Settlements</button></>:s?<button className="button gold" onClick={()=>navigate('settlements')}>Settle the table<ArrowRight size={16}/></button>:<><button className="button gold" onClick={()=>open('session')}><Plus size={17}/>Start a game</button><button className="button hero-secondary" onClick={()=>fileRef.current?.click()}><Upload size={15}/>Import history</button></>}</div></div></section>
  <div className="metric-grid">{[{label:'Buy-ins',value:money(st?.totalIn||0),hint:'',icon:Coins},{label:'Cashed out',value:money(st?.totalOut||0),hint:`${ids.filter((id:any)=>!playerStats(s,id).open).length}/${ids.length} counted`,icon:ArrowUpRight},{label:'Players',value:String(ids.length),hint:'',icon:Users},{label:s?.status==='closed'?'Difference':'In play',value:money(s?.status==='closed'?st?.unresolved||0:(st?.totalIn||0)-(st?.adjusted||0)),hint:s?.status==='closed'?(st?.unresolved?'Needs review':'Balanced'):'',icon:Wallet}].map((card,i)=><div className={`metric metric-${i}`} key={card.label}><div className="metric-label">{card.label}<card.icon size={16}/></div><strong>{card.value}</strong><span>{card.hint}</span></div>)}</div>
  <div className="dashboard-columns">{ledgerPanel}<aside className="right-rail"><button className="mini-player" onClick={()=>navigate('music')}><span className="mini-player-art">{music.room?.playing?.artwork?<img src={music.room.playing.artwork} alt=""/>:<Headphones size={24}/>}</span><span><small>Now playing</small><b>{music.room?.playing?.name||'Open music'}</b><em>{music.room?.playing?.artists||'Spotify'}</em></span><Play size={16}/></button><section className="panel activity-panel"><div className="panel-heading"><h2>Table activity</h2><button className="text-button" onClick={()=>navigate('activity')}>View all<ArrowRight size={14}/></button></div><Feed entries={s?.entries.filter((e:any)=>!e.voidedAt).slice(-5).reverse()||[]}/></section><button className="settle-note" onClick={()=>navigate('settlements')}><span className="note-icon"><ArrowLeftRight size={19}/></span><h3>Settle up</h3><ArrowRight size={17}/></button></aside></div>
  {s&&<div className="table-controls"><span><span className={`dot ${s.status==='closed'?'quiet':''}`}/>{s.status==='open'?'Game open':'Game closed'}</span><div>{s.status==='closed'&&!stats(s).unresolved&&<button onClick={()=>open('email')}><Mail size={14}/>Resend results</button>}<button onClick={()=>open('notes')}><NotebookPen size={14}/>Session notes</button><button onClick={exportCSV}><Download size={14}/>Export CSV</button>{s.status==='open'?<button onClick={()=>open('close')}><CheckCircle2 size={14}/>Close game</button>:<button onClick={()=>act('reopen-session',{sessionId:s.id},'The game is open again.')}><RotateCcw size={14}/>Reopen game</button>}</div></div>}
 </>;}
 function Players(){const profiles=playerProfiles(data),order=new Map(data.players.map((p:any,i:number)=>[p.id,i])),people=profiles.filter((p:any)=>p.name.toLowerCase().includes(query.toLowerCase())).sort((a:any,b:any)=>b.games-a.games||b.net-a.net);return <><div className="players-toolbar"><label className="search"><Search size={15}/><input aria-label="Find a player" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search"/></label><button className="button gold" onClick={()=>open('player')}><Plus size={16}/>Add player</button></div>{people.length?<div className="player-tiles">{people.map((p:any)=><PlayerCard key={p.id} profile={p} index={order.get(p.id) as number} email={privateProfiles.ready?privateProfiles.contacts[p.id]:null} onEmail={()=>open('edit-player',{playerId:p.id,name:p.name})}/>)}</div>:<div className="panel"><Empty icon={Users} title={query?'No match.':'No players yet.'} detail={query?'Try another name.':'Add your regulars.'}><button className="button primary" onClick={()=>open('player')}><Plus size={16}/>Add player</button></Empty></div>}</>;}
 function ActivityPage(){const entries=(s?.entries||[]).filter((e:any)=>(filter==='all'||e.type===filter)&&(!query||person(e.playerId||e.from).toLowerCase().includes(query.toLowerCase()))).slice().reverse();return <section className="panel"><div className="panel-heading"><div><h2>Activity</h2></div><button className="button secondary small-button" disabled={!s} onClick={exportCSV}><Download size={15}/>Export</button></div><div className="activity-toolbar"><div className="tabs">{[['all','All activity'],['buyin','Buy-ins'],['cashout','Cash-outs'],['transfer','Payments']].map(([id,label])=><button className={filter===id?'active':''} key={id} onClick={()=>setFilter(id)}>{label}</button>)}</div><label className="search"><Search size={15}/><input aria-label="Search activity by player" placeholder="Find a player…" value={query} onChange={e=>setQuery(e.target.value)}/></label></div><Feed entries={entries} full/></section>;}
 function Settlements(){
  if(!s)return <div className="panel"><Empty icon={ArrowLeftRight} title="No game selected." detail="Start a game to track chips and settle balances."><button className="button primary" onClick={()=>open('session')}>New game<ArrowRight size={16}/></button></Empty></div>;
  if(s.status==='open'&&s.mode==='decentralized'){const remaining=ids.filter((id:any)=>playerStats(s,id).open);return <div className="settlement-wait panel"><span className="eyebrow">FINAL CHIP COUNTS</span><h2>Finish the chip counts</h2><p>Record each player’s final chips, including $0 for bust-outs, then close the game to prepare the payment plan.</p><div className="cashout-progress"><span>Final chip counts</span><b>{ids.length-remaining.length} / {ids.length}</b><div><i style={{width:`${ids.length?(ids.length-remaining.length)/ids.length*100:0}%`}}/></div></div>{remaining.length>0&&<div className="remaining-players">{remaining.map((id:any,i:number)=><button key={id} onClick={()=>open('cashout',{playerId:id})}><Avatar name={person(id)} index={i} small/>{person(id)}<ArrowUpRight size={14}/></button>)}</div>}<div className="empty-actions"><button className="button primary" onClick={()=>open('cashout')}>Record cash-out<ArrowUpRight size={16}/></button><button className="button secondary" disabled={!!remaining.length} onClick={()=>open('close')}>Close game<Check size={16}/></button></div><span className="oversized-suit" aria-hidden="true">♠</span></div>;}
  const plan=simplify(s),pendingPayments=s.entries.filter((e:any)=>e.type==='transfer'&&e.status==='pending'&&!e.voidedAt),difference=stats(s).unresolved,unresolved=s.status==='closed'&&difference!==0;
  return <>{unresolved&&<section className="variance-callout"><AlertCircle size={22}/><div><h3>Chip counts don’t balance</h3><p>There’s a {money(difference)} difference between buy-ins and adjusted cash-outs. Review the ledger or record how your group agreed to share it.</p><div className="toolbar-actions"><button className="button secondary small-button" onClick={()=>open('allocate')}>Assign a share</button><button className="text-button" onClick={()=>{if(confirm('Allocate the difference equally across all participants?'))act('split-variance',{sessionId:s.id},'Difference shared equally.');}}>Split equally</button>{s.mode==='centralized'&&<button className="text-button" onClick={()=>{if(confirm('Assign the difference to the bank?'))act('split-variance',{sessionId:s.id,mode:'bank'},'Difference assigned to bank.');}}>Assign to bank</button>}</div></div></section>}
  <div className="settle-head"><h2>{plan.length?`${plan.length} payment${plan.length===1?'':'s'} left`:pendingPayments.length?'Waiting on confirmations':unresolved?'Needs review':'All settled'}</h2><div className="settle-actions"><button className="icon-button" title="Copy payment list" aria-label="Copy payment list" onClick={async()=>{try{await navigator.clipboard.writeText(`${s.title}\n${plan.map((p:any)=>`${person(p.from)} → ${person(p.to)}: ${money(p.amount)}`).join('\n')||'All settled.'}`);toast('Copied.');}catch{toast('Could not copy.');}}}><Copy size={16}/></button>{s.status==='closed'&&!unresolved&&<button className="button secondary" onClick={()=>open('email')}><Mail size={15}/>Resend results</button>}</div></div>
  {plan.length>0&&<section className="panel settle-list">{plan.map((p:any,i:number)=><div className="settle-row" key={`${p.from}-${p.to}`}><span className="settle-who"><Avatar name={person(p.from)} index={ids.indexOf(p.from)} small/><b>{person(p.from)}</b><ArrowRight size={15}/><Avatar name={person(p.to)} index={ids.indexOf(p.to)} small/><b>{person(p.to)}</b></span><strong>{money(p.amount)}</strong><button className="button gold small-button" disabled={unresolved} onClick={()=>act('transfer',{sessionId:s.id,from:p.from,to:p.to,amount:(p.amount/100).toFixed(2),method:'Other',paid:true,note:''},`${person(p.from)} → ${person(p.to)} marked paid.`)}><Check size={14}/>Mark paid</button></div>)}</section>}{!unresolved&&!plan.length&&!pendingPayments.length&&<div className="all-settled"><CheckCheck size={38}/><h3>Everyone’s square.</h3></div>}
  {pendingPayments.length>0&&<section className="panel"><div className="panel-heading"><h2>Waiting for confirmation <span className="count">{pendingPayments.length}</span></h2></div><Feed entries={pendingPayments} full/></section>}
  <details className="math-details"><summary>Show the math</summary><div className="math-body"><div className="table-scroll"><table><thead><tr><th>Player</th><th>Final chips</th><th>− Buy-ins</th><th>+ Adjustments</th><th>+ Buy-ins paid</th><th>+ Sent − Received</th><th>Still owed / due</th><th>+ Pending sent − received</th><th>Balance for new payments</th></tr></thead><tbody>{ids.map((id:any)=>{const c=balanceCalculation(s,id);return <tr key={id}><td><b>{person(id)}</b></td><td className="numeric">{money(c.cashed)}</td><td className="numeric">{money(c.bought)}</td><td className="numeric">{signedMoney(c.adjustment)}</td><td className="numeric">{money(c.paidIn)}</td><td className="numeric">{signedMoney(c.confirmed)}</td><td className={`numeric ${c.balance<0?'negative':'positive'}`}>{signedMoney(c.balance)}</td><td className="numeric">{signedMoney(c.pending)}</td><td className="numeric">{signedMoney(c.plannedBalance)}</td></tr>;})}{(balances(s).get(BANK_ID)||0)!==0&&<tr><td><b>{person(BANK_ID)}</b></td><td colSpan={5}>Clearing balance: buy-ins − received buy-ins − final chips − adjustments + sent − received transfers</td><td className="numeric">{signedMoney(balances(s).get(BANK_ID)||0)}</td><td className="numeric">{signedMoney(balanceCalculation(s,BANK_ID).pending)}</td><td className="numeric">{signedMoney(balanceCalculation(s,BANK_ID).plannedBalance)}</td></tr>}</tbody></table></div><div className="calculation-note">Final chips − buy-ins + adjustments + buy-ins already paid + confirmed payments sent − confirmed payments received = remaining balance. Pending transfers reserve their amount in the plan below, but remain unpaid until confirmed.</div><details className="netting-details"><summary>How balances become direct payments</summary><p>Match the largest remaining amount owed with the largest amount due. Each transfer is the smaller of those two balances. Repeat until the remaining balances are zero.</p><ol>{settlementSteps(s).map((step:any,i:number)=><li key={i}><b>{person(step.from)} pays {person(step.to)} {money(step.amount)}</b><span>min({money(step.owedBefore)} owed, {money(step.dueBefore)} due) = {money(step.amount)}</span><small>{person(step.from)} owes {money(step.owedAfter)} afterward; {person(step.to)} is still due {money(step.dueAfter)}.</small></li>)}</ol>{!plan.length&&<p>No additional transfers are needed. Check any payments awaiting confirmation below.</p>}</details></div></details>
  {s.adjustments.filter((a:any)=>!a.voidedAt).length>0&&<section className="panel"><div className="panel-heading"><h2>Agreed adjustments</h2></div>{s.adjustments.filter((a:any)=>!a.voidedAt).map((a:any)=><div className="adjustment-row" key={a.id}><span>{person(a.playerId)}<small>{a.note}</small></span><b>{signedMoney(a.amount)}</b><button className="text-button" onClick={()=>act('undo-allocation',{sessionId:s.id,allocationId:a.id},'Adjustment undone.')}>Undo</button></div>)}</section>}<div className="table-controls"><button className="text-button" onClick={()=>open('transfer')}><Plus size={14}/>Record a different payment</button></div></>;
 }

 function remind(ids:string[]){if(privateProfiles.ready){const missing=ids.filter(id=>!privateProfiles.contacts[id]?.email||privateProfiles.contacts[id]?.enabled===false);if(missing.length===ids.length){toast(`No email saved for ${missing.map(person).join(', ')}. Add one on Players.`);return;}ids=ids.filter(id=>!missing.includes(id));}act('send-reminders',{playerIds:ids},`Reminder sent to ${ids.map(person).join(', ')}.`);}
 function OwedPage(){
  const total=debtors.reduce((n:number,d:any)=>n+d.total,0);
  if(!debtors.length)return <div className="all-settled"><CheckCheck size={38}/><h3>Everyone’s square.</h3></div>;
  return <><div className="settle-head"><h2>{money(total)} unpaid</h2><div className="settle-actions"><button className="button secondary" onClick={()=>remind(debtors.map((d:any)=>d.id))}><BellRing size={15}/>Remind all</button></div></div>
  <div className="debtor-list">{debtors.map((d:any)=><section className="panel debtor" key={d.id}><header><Avatar name={person(d.id)} index={data.players.findIndex((p:any)=>p.id===d.id)}/><span className="debtor-name"><b>{person(d.id)}</b><small><Ban size={12}/>Can’t buy in until paid</small></span><strong className="negative">{money(d.total)}</strong><button className="icon-button remind-button" title={`Remind ${person(d.id)}`} aria-label={`Remind ${person(d.id)}`} onClick={()=>remind([d.id])}><BellRing size={16}/></button></header>
   {d.items.map((t:any)=><div className="settle-row" key={`${t.game.id}-${t.to}`}><span className="settle-who"><ArrowRight size={15}/><Avatar name={person(t.to)} index={data.players.findIndex((p:any)=>p.id===t.to)} small/><b>{person(t.to)}</b><a className="debt-game" href={routePath('settlements',t.game.id)} onClick={e=>{e.preventDefault();go('settlements',t.game.id);}}>{t.game.title}</a></span><strong>{money(t.amount)}</strong><button className="button gold small-button" onClick={()=>act('transfer',{sessionId:t.game.id,from:d.id,to:t.to,amount:(t.amount/100).toFixed(2),method:'Other',paid:true,note:''},`${person(d.id)} → ${person(t.to)} marked paid.`)}><Check size={14}/>Mark paid</button></div>)}
  </section>)}</div></>;
 }
 function HistoryPage(){return <section className="panel"><div className="panel-heading"><div><h2>Games <span className="count">{data.sessions.length}</span></h2></div><button className="button primary" onClick={()=>open('session')}><Plus size={16}/>New game</button></div>{data.sessions.length?<div className="history-list">{[...data.sessions].reverse().map((game:any,i:number)=>{const summary=stats(game);return <a className="history-row" href={routePath('game',game.id)} key={game.id} onClick={e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();selectGame(game.id);}}><span className="history-icon"><Spade size={21}/></span><div><h3>{game.title}</h3><p>{formatDate(game.createdAt)}<span>·</span>{participants(game).length} players<span>·</span>{game.mode==='centralized'?'Central banker':'Pay at end'}</p></div><span className={`status-pill ${game.status==='open'?'live':'neutral'}`}><i/>{game.status==='open'?'In progress':'Closed'}</span><strong>{money(summary.totalIn)}<small>Total buy-ins</small></strong><ChevronRight size={18}/></a>;})}</div>:<Empty icon={History} title="No games recorded." detail="Create a session to begin your history."/>}</section>;}
 function Settings(){return <><EmailSettings editor={editor} unlock={()=>open('unlock')}/><div className="settings-grid"><section className="panel"><div className="panel-heading"><h2>Ledger</h2><CloudCheck size={21}/></div><div className={`connection-card ${!online?'offline':''}`}><span><SyncIcon size={23} className={saving?'spinning':''}/></span><div><h3>{syncLabel}</h3><p>{online?'Saved to the cloud. Changes appear on other devices.':'Offline. Changes will retry when you reconnect.'}</p>{updatedAt&&<small>Last cloud save: {new Date(updatedAt).toLocaleString()}</small>}</div></div>{!online&&<button className="button secondary" onClick={()=>retry()}><RotateCcw size={15}/>Retry</button>}</section><div><section className="panel"><div className="panel-heading"><h2>Backups</h2><Download size={20}/></div><p className="panel-description">Download, export, or import your games.</p><div className="settings-buttons"><button className="button secondary" onClick={()=>navigate('history')}><History size={16}/>View game history</button><button className="button secondary" onClick={()=>navigate('activity')}><Activity size={16}/>View transaction activity</button><button className="button primary" onClick={exportJSON}><Download size={16}/>Download JSON backup</button><button className="button secondary" disabled={!s} onClick={exportCSV}><Download size={16}/>Export current game as CSV</button><button className="button secondary" onClick={()=>fileRef.current?.click()}><Upload size={16}/>Import ledger backup</button></div></section></div></div></>;}
 const titles:Record<Page,string>={owed:'Settlements',game:s?.title||'Game',missing:'Page not found',overview:'Dashboard',players:'Players',activity:'Activity',settlements:'Settlements',history:'Games',settings:'Settings',music:'Music'};
 const modalTitles:Record<string,string>={email:'Resend results',session:'New game',player:'Add a player', 'edit-player':'Edit player',buyin:'Record buy-in',cashout:'Record cash-out',transfer:'Record payment',close:'Close game',notes:'Table notes',share:'Share table',void:'Correct entry',allocate:'Allocate difference',unlock:'Unlock editing'};
 const playerOptions=(withBank=false,blockDebtors=false)=> <>{withBank&&<option value={BANK_ID}>{person(BANK_ID)}</option>}{data.players.map((p:any)=>{const owes=blockDebtors&&debts.get(p.id);return <option value={p.id} key={p.id} disabled={!!owes}>{p.name}{owes?` (owes ${money(owes.reduce((n:number,d:any)=>n+d.amount,0))})`:''}</option>;})}</>;
 const allSaved=online&&ready&&!saving&&!pending;
 return <div className="app-shell" data-motion={motion?'on':'off'}>{intro&&<Intro onDone={()=>setIntro(false)}/>}<div className="app-atmosphere" aria-hidden="true"><video ref={videoRef} className="room-background" src="/felt-club-table.mp4" poster="/felt-club-table.jpg" autoPlay={motion} muted loop playsInline preload="auto"/><div className="app-background-overlay"/></div><div className="app-content"><a className="skip-link" href="#main">Skip to content</a><aside className="sidebar"><a className="brand" href="/" onClick={e=>{e.preventDefault();navigate('overview');}}><span className="brand-icon"><Club size={30} strokeWidth={1.15}/></span><span>Felt Club<small>Poker OS</small></span></a><nav aria-label="Main navigation">{navigation.map(({id,label,icon:Icon})=><button key={id} className={`nav-item ${(page===id||(id==='history'&&page==='game'))?'active':''}`} onClick={()=>navigate(id)}><Icon size={18}/>{label}{id==='owed'&&debtors.length>0&&<span className="nav-count">{debtors.length}</span>}</button>)}</nav> <div className="sidebar-bottom"><button className="nav-item" onClick={()=>open('share')}><Share2 size={18}/>Share</button><button className={`nav-item ${page==='settings'?'active':''}`} onClick={()=>navigate('settings')}><SlidersHorizontal size={18}/>Settings</button></div></aside>
 <div className="main-shell"><header className="topbar"><div className="breadcrumb">{page==='game'||sessionId?<><a href="/games" onClick={e=>{e.preventDefault();navigate('history');}}>Games</a><ChevronRight size={13}/><b>{s?.title||titles[page]}</b></>:<b>{titles[page]}</b>}</div><div className="topbar-right"><button className="motion-toggle icon-button" aria-label={motion?'Pause background video':'Play background video'} title={motion?'Pause background video':'Play background video'} onClick={()=>setMotion(v=>!v)}>{motion?<Pause size={16}/>:<Play size={16}/>}</button><button className={`cloud-status icon-button ${!online?'offline':''} ${allSaved?'':'busy'}`} onClick={()=>navigate('settings')} title={updatedAt?`${syncLabel} · last cloud save ${new Date(updatedAt).toLocaleString()}`:syncLabel} aria-label={syncLabel}><SyncIcon size={16} className={saving||!ready?'spinning':''}/>{!allSaved&&<span>{syncLabel}</span>}</button><button className={`lock-toggle icon-button ${editor?'unlocked':''}`} title={editor?'Editing unlocked · click to lock':'Unlock editing'} aria-label={editor?'Lock editing':'Unlock editing'} onClick={()=>editor?void apiFetch('/api/access',{method:'DELETE'}).then(()=>{setEditorToken(null);setEditor(false);editorRef.current=false;toast('Editing locked.');}):open('unlock')}>{editor?<LockKeyholeOpen size={16}/>:<LockKeyhole size={16}/>}</button><button className="spotify-top icon-button" title={music.connected?(music.profile?.display_name||'Spotify connected'):'Connect Spotify'} aria-label={music.connected?'Open music':'Connect Spotify'} onClick={()=>music.connected?navigate('music'):music.login()}>{music.profile?.images?.[0]?.url?<img src={music.profile.images[0].url} alt=""/>:<SpotifyMark/>}</button><button className="icon-button share-icon" title="Share" aria-label="Share this page" onClick={()=>open('share')}><Share2 size={16}/></button></div></header>
 <main id="main" className={page==='overview'?'overview-page':page==='game'?'game-page':undefined}><div className="page-heading"><div>{page!=='game'&&<h1>{titles[page]}</h1>}</div><div className="heading-actions">{page!=='overview'&&page!=='players'&&page!=='settings'&&page!=='music'&&page!=='owed'&&gameSelect}{page!=='players'&&<button className="button primary new-game" onClick={()=>open('session')}><Plus size={16}/>New game</button>}</div></div>
 {sessionId&&s&&<nav className="game-tabs" aria-label="Game navigation"><a href="/games" onClick={e=>{e.preventDefault();navigate('history');}}>All games</a><span>/</span>{[{id:'game',label:'Game'},{id:'activity',label:'Activity'},{id:'settlements',label:'Settlements'}].map(tab=><a key={tab.id} className={page===tab.id?'active':''} href={routePath(tab.id,s.id)} onClick={e=>{e.preventDefault();go(tab.id as Page,s.id);}}>{tab.label}</a>)}<button className="text-button" onClick={()=>open('share')}><Copy size={14}/>Share game</button></nav>}
 {!online&&<div className="connection-banner" role="status"><CloudOff size={16}/>{pending?'Your changes are saved on this device and will sync when you reconnect.':'Showing the last saved table. Reconnecting automatically.'}<button onClick={()=>retry()}>Retry</button></div>}
 {error&&<div className="error-banner" role="alert"><AlertCircle size={17}/><span>{error} The rejected action is preserved on this device for recovery.</span><button aria-label="Dismiss error" onClick={clearError}><X size={15}/></button></div>}
 {!ready&&!data.sessions.length?<div className="loading-state"><LoaderCircle className="spinning" size={25}/><span>Loading games…</span></div>:page==='missing'||(ready&&sessionId&&!s)?<section className="panel"><Empty title="Game or page not found" detail="Check the link or choose a game from your history."><button className="button primary" onClick={()=>navigate('history')}>View games</button></Empty></section>:page==='overview'?<Dashboard data={data} onGame={selectGame} onNew={()=>open('session')} onGames={()=>navigate('history')} onPlayers={()=>navigate('players')}/>:page==='game'?GamePage():page==='players'?Players():page==='activity'?ActivityPage():page==='owed'?OwedPage():page==='settlements'?Settlements():page==='history'?HistoryPage():page==='music'?<MusicPanel music={music} session={s} editor={editor} unlock={()=>open('unlock')}/>:Settings()}</main></div>
 <nav className="mobile-nav" aria-label="Mobile navigation">{[{id:'overview',label:'Home',icon:LayoutDashboard},{id:'history',label:'Games',icon:History},{id:'players',label:'Players',icon:Users},{id:'owed',label:'Settle up',icon:ArrowLeftRight},{id:'settings',label:'Settings',icon:SlidersHorizontal}].map(({id,label,icon:Icon})=><button key={id} className={(page===id||(id==='history'&&page==='game'))?'active':''} onClick={()=>navigate(id as Page)}><Icon size={20}/><span>{label}</span></button>)}</nav>
 <input type="file" ref={fileRef} accept=".json,application/json" hidden onChange={e=>{const file=e.target.files?.[0];if(file)void importFile(file);e.target.value='';}}/>
 {notice&&<div className="toast" role="status"><CheckCircle2 size={17}/>{notice}<button onClick={()=>setNotice('')} aria-label="Dismiss notification"><X size={14}/></button></div>}
 <dialog ref={dialogRef} onCancel={()=>setModal('')} onClick={e=>{if(e.target===e.currentTarget)setModal('');}} aria-labelledby="modal-title"><div className="dialog-inner"><div className="dialog-heading"><span className="modal-icon"><Spade size={20}/></span><button className="icon-button" type="button" aria-label="Close dialog" onClick={()=>setModal('')}><X size={20}/></button></div><h2 id="modal-title">{modalTitles[modal]}</h2>
 {modal==='share'?<><p className="dialog-description">Share this page. Anyone with the link can view it; changes require the passcode.</p><div className="share-link"><span>{typeof window!=='undefined'?window.location.origin+window.location.pathname:''}</span><button className="icon-button" aria-label="Copy table link" onClick={async()=>{try{await navigator.clipboard.writeText(window.location.origin+window.location.pathname);toast('Link copied.');}catch{setFormError('Could not copy. Select the URL in your address bar.');}}}><Copy size={17}/></button></div><p className="fine-print"><LockKeyhole size={13}/>Viewing is open. Editing requires the table passcode.</p></>:<form key={modal+JSON.stringify(preset)+(modal==='edit-player'||modal==='email'?String(privateProfiles.ready):'')} onSubmit={submit}>
 {modal==='unlock'&&<><p className="dialog-description">Anyone can follow the game. Enter the table passcode to record buy-ins, cash-outs, and payments.</p><label>Editing passcode<input className="passcode-input" name="passcode" type="password" autoComplete="current-password" required autoFocus placeholder="Enter passcode"/></label><div className="form-note"><LockKeyhole size={17}/><p>This browser remembers your editor session. Lock editing whenever you’re done.</p></div></>}
 {modal==='email'&&<><p className="dialog-description">Resend each player their results and what they owe or are owed.</p>{!privateProfiles.ready?<p className="fine-print">{privateProfiles.error||'Loading email addresses…'}</p>:<div className="email-picker">{ids.map((id:any,i:number)=>{const c=privateProfiles.contacts[id],ok=!!c?.email&&c.enabled!==false;return <label key={id} className={`email-pick ${ok?'':'disabled'}`}><input type="checkbox" name="playerIds" value={id} defaultChecked={ok} disabled={!ok}/><Avatar name={person(id)} index={i} small/><span><b>{person(id)}</b><small>{c?.email?(c.enabled===false?'Updates off':c.email):'No email'}</small></span>{!c?.email&&<button type="button" className="text-button" onClick={()=>open('edit-player',{playerId:id,name:person(id)})}>Add</button>}</label>;})}</div>}</>}
 {(modal==='session')&&<><p className="dialog-description">Enter the details for this session.</p><label>Game name<input name="title" required maxLength={100} autoFocus defaultValue={`Poker night, ${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric'})}`} placeholder="Friday night poker"/></label><label>How are you playing?<select name="mode" defaultValue="decentralized"><option value="decentralized">Pay at the end · direct settlement</option><option value="centralized">Centralized · one banker collects</option></select></label><div className="form-note"><ArrowLeftRight size={18}/><p>Record chips now, then settle net wins and losses after the game.</p></div></>}
 {(modal==='player'||modal==='edit-player')&&<><p className="dialog-description">Add a regular to your player directory.</p><label>Player name<input name="name" required maxLength={100} autoFocus defaultValue={preset.name||''} placeholder="Player name"/></label><label>Email address <span className="optional">optional · private</span><input name="email" type="email" autoComplete="email" maxLength={254} defaultValue={modal==='edit-player'?privateProfiles.contacts[preset.playerId]?.email||'':''} placeholder="player@example.com" disabled={modal==='edit-player'&&!privateProfiles.ready}/></label><label className="checkbox-label"><input type="checkbox" name="emailEnabled" defaultChecked={modal==='player'||privateProfiles.contacts[preset.playerId]?.enabled!==false}/>Send email updates for this player</label><p className="fine-print">Emails cover buy-ins, cash-outs, payments, and final balances. Addresses are visible only to the editor. Connect an email sender in Settings to start delivery.</p>{modal==='edit-player'&&!privateProfiles.ready&&<p className="fine-print">{privateProfiles.error||'Loading private email address…'}</p>}</>}
 {(modal==='buyin'||modal==='cashout')&&<><p className="dialog-description">{modal==='buyin'?'Record the value of chips issued to this player.':'Record the final value of their chips. This doesn’t record a payment.'}</p><label>Player<select name="playerId" required value={selectedPlayer} onChange={e=>setSelectedPlayer(e.target.value)}><option value="" disabled>Choose a player</option>{playerOptions(false,modal==='buyin')}{modal==='buyin'&&<option value="__new">＋ Someone new</option>}</select></label>{selectedPlayer==='__new'&&<label>New player’s name<input name="newName" required maxLength={100} placeholder="Player name"/></label>}<label>{modal==='buyin'?'Buy-in amount':'Final chip value'}<div className="money-input"><span>$</span><input name="amount" type="number" inputMode="decimal" min={modal==='cashout'?'0':'0.01'} step="0.01" required defaultValue={preset.amount||''} placeholder={modal==='buyin'?'20.00':'0.00'}/><span>USD</span></div></label>{modal==='buyin'&&<div className="quick-amounts">{[10,20,40,50,100].map(n=><button key={n} type="button" onClick={e=>{const input=e.currentTarget.closest('form')?.querySelector<HTMLInputElement>('[name="amount"]');if(input){input.value=n.toFixed(2);input.focus();}}}>${n}</button>)}</div>}{modal==='buyin'&&s?.mode==='centralized'?<><label>Payment method<select name="method">{METHODS.map(m=><option key={m}>{m}</option>)}</select></label><label className="checkbox-label"><input name="received" type="checkbox" defaultChecked/>Banker has received the funds</label></>:modal==='buyin'?<div className="form-note"><CheckCheck size={18}/><p>Chips now, money later. Payment details are collected when settling the final net result.</p></div>:<div className="form-note"><Coins size={18}/><p>Busted out? Record $0. Every player needs a final chip count before closing the game.</p></div>}<label>Note <span className="optional">optional</span><input name="note" maxLength={150} placeholder={modal==='buyin'?'Rebuy, extra stack…':'Anything to remember…'}/></label></>}
 {modal==='transfer'&&<><p className="dialog-description">Choose how the money moved. Only mark paid after confirming the transfer.</p><div className="form-row"><label>Paid by<select name="from" defaultValue={preset.from||BANK_ID}>{playerOptions(true)}</select></label><label>Paid to<select name="to" defaultValue={preset.to||data.players[0]?.id}>{playerOptions(true)}</select></label></div><label>Amount<div className="money-input"><span>$</span><input name="amount" type="number" min="0.01" step="0.01" inputMode="decimal" required defaultValue={preset.amount||''} placeholder="0.00"/><span>USD</span></div></label><label>Payment method<select name="method">{METHODS.map(m=><option key={m}>{m}</option>)}</select></label><label className="checkbox-label"><input name="paid" type="checkbox"/>Payment sent and confirmed</label><label>Note <span className="optional">optional</span><input name="note" maxLength={150} placeholder="Partial payment, etc."/></label><div className="form-note"><LockKeyhole size={17}/><p>This records a payment. It never sends money.</p></div></>}
 {modal==='close'&&<><p className="dialog-description">Closing locks in the chip counts and prepares your settlement plan. You can reopen the game later.</p><div className="close-summary"><span>Total buy-ins<b>{money(st?.totalIn||0)}</b></span><span>Final chips<b>{money(st?.totalOut||0)}</b></span><span>Difference<b>{money(st?.unresolved||0)}</b></span></div>{ids.some((id:any)=>playerStats(s,id).open)&&<div className="form-warning">Still waiting on: {ids.filter((id:any)=>playerStats(s,id).open).map((id:any)=>person(id)).join(', ')}. Record their cash-outs first.</div>}</>}
 {modal==='notes'&&<><p className="dialog-description">Add rules or other details for this game.</p><label>Session notes<textarea name="notes" rows={6} maxLength={5000} defaultValue={s?.notes||''} placeholder="Anything worth keeping…" autoFocus/></label></>}
 {modal==='void'&&<><p className="dialog-description">The original entry will stay in the activity history, marked as voided. Record a replacement afterward if needed.</p><label>Reason<input name="note" maxLength={150} placeholder="Entered the wrong amount…" autoFocus/></label></>}
 {modal==='allocate'&&<><p className="dialog-description">Only record a discrepancy allocation your group agreed to. Remaining difference: {money(st?.unresolved||0)}.</p><label>Player<select name="playerId" required><option value="">Choose a participant</option>{ids.map((id:any)=><option key={id} value={id}>{person(id)}</option>)}</select></label><label>Share of difference ($)<input name="amount" type="number" min="0.01" step="0.01" max={Math.abs(st?.unresolved||0)/100} required/></label><label>Agreed reason<input name="note" required maxLength={150} placeholder="What the table agreed to"/></label></>}
 {formError&&<p className="form-error" role="alert"><AlertCircle size={15}/>{formError}</p>}
 <div className="dialog-actions"><button className="button secondary" type="button" onClick={()=>setModal('')}>Cancel</button><button className={`button ${modal==='void'?'danger':'primary'}`} type="submit">{modal==='unlock'?'Unlock editing':modal==='email'?'Send emails':modal==='session'?'Create game':modal==='player'?'Add player':modal==='buyin'?'Record buy-in':modal==='cashout'?'Record cash-out':modal==='transfer'?'Record payment':modal==='close'?'Close game':modal==='void'?'Void entry':'Save'}{modal==='void'?<RotateCcw size={15}/>:modal==='email'?<Send size={15}/>:<ArrowRight size={16}/>}</button></div><p className="auto-save-note"><CloudCheck size={12}/>Automatically saved to your table.</p></form>}{modal==='share'&&formError&&<p className="form-error">{formError}</p>}
 </div></dialog></div></div>;
}
